<?php declare(strict_types="1"); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Image Flip Tool','description'=>'Flip an image horizontally or vertically in your browser.','url'=>'https://smarttoolz.in/tools/image-flip/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Image Flip Tool</h1><p>Flip images horizontally or vertically.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="image/*"><select id="m"><option value="x">Horizontal</option><option value="y">Vertical</option></select><button id="go" class="tool-btn">Flip Image</button><a id="d" class="tool-btn" hidden download="flipped.png">Download</a></div></section></main><script>go.onclick=()=>{let f=document.getElementById('f').files[0];if(!f)return;let i=new Image;i.onload=()=>{let c=document.createElement('canvas');c.width=i.width;c.height=i.height;let x=c.getContext('2d');if(m.value==='x'){x.translate(c.width,0);x.scale(-1,1)}else{x.translate(0,c.height);x.scale(1,-1)}x.drawImage(i,0,0);c.toBlob(b=>{d.href=URL.createObjectURL(b);d.hidden=false},'image/png')};i.src=URL.createObjectURL(f)}</script><?php smarttoolz_tool_page_end(); ?>